-- ============================================================================
-- QHUB R15.6 — 26 MIGRATION-HISTORY RECORD (ONE TRANSACTION — PREPARED, NOT YET
-- AUTHORIZED FOR EXECUTION)
--
-- Records EXACTLY ONE complete, CLI-compatible migration-history row and changes
-- nothing else:
--
--   INSERT INTO supabase_migrations.schema_migrations (version, name, statements)
--   VALUES ('20260729', 'commercial_launch_foundation', <the 89 CLI-parsed statements>);
--
-- EVERY FIELD IS DERIVED, NOT GUESSED.
--   * version + name come from the pinned CLI's filename parser
--     (^([0-9]+)_(.*)\.sql$, extracted verbatim from the installed
--     supabase@2.110.0 binary, sha256
--     14814afa6fe59081eb9f24709fc077226bf89bc25cf77ee3bcb19565f3ef8899) applied
--     to the committed migration file (sha256
--     1509eb59056764b0b6500aa8bfbb2df65eb330a1ff363758bff0e4797427a755, 125,186
--     bytes).
--   * statements is the EXACT text[] the pinned CLI itself recorded when invoked
--     by explicit local path against an isolated localhost scratch database
--     (three independent runs, byte-identical): cardinality 89, total statement
--     bytes 124,959, canonical digest 7b28ccf3ba7cae3e29c17bc5c3be60b6
--     (md5 over octet_length(elem)||':'||elem concatenated in order). All 89
--     statements are verbatim substrings of the committed migration, in order.
--     The array is embedded below as single-line base64 INSERT DATA: it is
--     decoded, integrity-checked and inserted — never interpreted, never
--     executed, no dynamic SQL, no EXECUTE. Base64 lines contain no LF/CRLF-
--     sensitive bytes, so a line-ending-normalizing transfer channel cannot
--     corrupt the payload undetected (and the digest gate would refuse it
--     anyway).
--
-- WHY SQL AND NOT `supabase migration repair --status applied 20260729`:
-- the installed CLI's repair path performs INSERT ... ON CONFLICT (version) DO
-- UPDATE — it silently OVERWRITES a conflicting row, cannot refuse ambiguous
-- history state, and cannot gate on the commercial verifier being READY. This
-- artifact records the identical complete row with every refusal the CLI lacks.
--
-- CONCURRENCY: the transaction acquires
--   LOCK TABLE supabase_migrations.schema_migrations IN SHARE ROW EXCLUSIVE MODE
-- before ANY authorization state is trusted. SHARE ROW EXCLUSIVE conflicts with
-- ROW EXCLUSIVE (every INSERT/UPDATE/DELETE writer, including a concurrent CLI
-- repair) and with itself (two concurrent runs of this file serialize), while
-- still allowing plain readers. Every gate below runs AFTER the lock is held, so
-- no writer can change the table between validation and the INSERT, and the lock
-- is held through COMMIT. This is proven by two-session tests against a real
-- PostgreSQL 16 server.
--
-- ISOLATION: READ COMMITTED, declared explicitly — after the lock is acquired,
-- every read observes the newest committed state (a REPEATABLE READ snapshot
-- could have been taken before the lock and would not see a racing commit).
--
-- SEARCH PATH: SET LOCAL search_path = pg_catalog, and every non-catalog object
-- is schema-qualified (supabase_migrations.schema_migrations,
-- public.qhub_verify_commercial_schema, pg_temp.r15_6_migration_history_audit).
-- pg_temp is never implicitly searched for functions, and no unqualified
-- relation reference exists, so temp or user objects cannot shadow anything.
--
-- FAIL-CLOSED GATES (each raises a deterministic exception BEFORE the insert;
-- any exception rolls back the entire transaction, including the temp audit
-- table; nothing is normalized, updated or deleted — this file contains no
-- UPDATE, DELETE, or ON CONFLICT path):
--   migration_history_payload_integrity    embedded statements payload does not
--                                          decode to the pinned cardinality/
--                                          bytes/digest (mangled transfer)
--   unexpected_runtime_verifier_state      verifier missing, overloaded, or body
--                                          not an approved digest
--   unexpected_runtime_verifier_authority  verifier signature/return/language/
--                                          kind/volatility/security/owner/
--                                          search_path/ACL/effective-executor
--                                          drift
--   migration_history_product_not_ready    verifier result not exactly
--                                          ready=true + exact version +
--                                          failed=[] (NULL-safe: a NULL or
--                                          malformed JSON field is NOT READY)
--   unexpected_migration_history_shape     any deviation from the pinned CLI
--                                          table contract (columns, positions,
--                                          types, nullability, defaults,
--                                          identity/generated, PK, constraint or
--                                          index inventory, triggers, rules,
--                                          policies, RLS, inheritance,
--                                          partitioning, persistence, kind,
--                                          owner)
--   migration_history_conflict             target under another name, NULL-name
--                                          or wrong/NULL/incomplete-statements
--                                          row (never updated — a STOP), the
--                                          name under another version, any
--                                          malformed recorded version, any
--                                          version newer than 20260729
--
-- ALREADY-CORRECT STATE: if exactly one row exists with the exact version, exact
-- name, and statements exactly matching the pinned cardinality + digest, this is
-- a true no-op (no durable DML at all) reported as ALREADY_RECORDED_EXACTLY.
--
-- TEMPORARY AUDIT: pg_temp.r15_6_migration_history_audit is created INSIDE the
-- transaction, without IF NOT EXISTS. A pre-existing object of that name (e.g. a
-- same-session rerun) fails the CREATE and aborts before anything else — rerunS
-- require a FRESH SESSION by design. Exactly one audit row is written on the
-- single success path. On any failure the rollback removes the table and its
-- row. The post-COMMIT SELECT reads ONLY this captured transaction evidence —
-- it does not re-query durable state; POST 27 is the certification of durable
-- state. After COMMIT the temp table lives until the session ends (or the
-- operator closes the editor session); it holds no sensitive data. If the
-- connection is lost mid-run, the transaction — including the audit table —
-- rolls back server-side; run a fresh read-only PRE 25 to disambiguate before
-- anything else.
--
-- MUTATION INVENTORY (complete):
--   durable:   at most ONE row inserted into
--              supabase_migrations.schema_migrations
--   temporary: pg_temp.r15_6_migration_history_audit (created in-transaction,
--              exactly one row, session-local, removed by rollback or session
--              end)
--   nothing else: no schema/table/function/trigger/ACL/policy/role/founder/
--   entitlement/billing/Stripe change; the commercial migration is NOT
--   re-executed; no stored statement text is ever interpreted or executed.
--
-- Run ONCE, in full, in a FRESH SESSION, only after
-- 25_PRE_MIGRATION_HISTORY_VERIFY.sql returned SAFE_TO_RECORD_MIGRATION_HISTORY
-- (or ALREADY_RECORDED_EXACTLY, where running this file is a permitted no-op).
-- The FINAL SELECT is the audit record — capture it verbatim.
--
-- TRANSFER SAFELY OR NOT AT ALL:
--   Get-Content -Raw -Encoding UTF8 <file> | Set-Clipboard
-- ============================================================================

BEGIN;

SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
SET LOCAL search_path = pg_catalog;

-- In-transaction, exact-name, no IF NOT EXISTS: a pre-existing object aborts the
-- whole run before any gate — same-session reruns are deliberately rejected.
CREATE TEMP TABLE r15_6_migration_history_audit (
  recorded_at             timestamptz NOT NULL,
  action                  text        NOT NULL,
  history_version         text        NOT NULL,
  history_name            text        NOT NULL,
  statements_cardinality  int         NOT NULL,
  statements_digest       text        NOT NULL,
  statements_total_bytes  bigint      NOT NULL,
  rows_for_version        int         NOT NULL,
  total_history_rows      int         NOT NULL
);

DO $r15_6_record$
