    pg_catalog.convert_from(pg_catalog.decode('R1JBTlQgRVhFQ1VURSBPTiBGVU5DVElPTiBwdWJsaWMucWh1Yl9yZWNvcmRfYWNrbm93bGVkZ21lbnQoVEVYVCwgVVVJRCwgVEVYVCwgVEVYVCkgVE8gc2VydmljZV9yb2xl', 'base64'), 'UTF8'),
    pg_catalog.convert_from(pg_catalog.decode('UkVWT0tFIEFMTCBPTiBGVU5DVElPTiBwdWJsaWMucWh1Yl9jYW5vbl9jZWxscyhURVhUW10pIEZST00gUFVCTElDLCBhbm9uLCBhdXRoZW50aWNhdGVk', 'base64'), 'UTF8'),
    pg_catalog.convert_from(pg_catalog.decode('R1JBTlQgRVhFQ1VURSBPTiBGVU5DVElPTiBwdWJsaWMucWh1Yl9jYW5vbl9jZWxscyhURVhUW10pIFRPIHNlcnZpY2Vfcm9sZQ==', 'base64'), 'UTF8'),
    pg_catalog.convert_from(pg_catalog.decode('UkVWT0tFIEFMTCBPTiBGVU5DVElPTiBwdWJsaWMucWh1Yl9jcmVhdGVfcHJvamVjdChURVhULCBURVhULCBURVhULCBURVhUKSBGUk9NIFBVQkxJQywgYW5vbiwgYXV0aGVudGljYXRlZA==', 'base64'), 'UTF8'),
    pg_catalog.convert_from(pg_catalog.decode('R1JBTlQgRVhFQ1VURSBPTiBGVU5DVElPTiBwdWJsaWMucWh1Yl9jcmVhdGVfcHJvamVjdChURVhULCBURVhULCBURVhULCBURVhUKSBUTyBzZXJ2aWNlX3JvbGU=', 'base64'), 'UTF8'),
    pg_catalog.convert_from(pg_catalog.decode('UkVWT0tFIEFMTCBPTiBGVU5DVElPTiBwdWJsaWMucWh1Yl9jb25zdW1lX2NoZWNrb3V0X2ludGVudChVVUlELCBURVhULCBURVhULCBURVhULCBURVhULCBURVhULCBURVhULCBURVhUKSBGUk9NIFBVQkxJQywgYW5vbiwgYXV0aGVudGljYXRlZA==', 'base64'), 'UTF8'),
    pg_catalog.convert_from(pg_catalog.decode('R1JBTlQgRVhFQ1VURSBPTiBGVU5DVElPTiBwdWJsaWMucWh1Yl9jb25zdW1lX2NoZWNrb3V0X2ludGVudChVVUlELCBURVhULCBURVhULCBURVhULCBURVhULCBURVhULCBURVhULCBURVhUKSBUTyBzZXJ2aWNlX3JvbGU=', 'base64'), 'UTF8'),
    pg_catalog.convert_from(pg_catalog.decode('', 'base64'), 'UTF8'),
    pg_catalog.convert_from(pg_catalog.decode('', 'base64'), 'UTF8'),
    pg_catalog.convert_from(pg_catalog.decode('UkVWT0tFIEFMTCBPTiBGVU5DVElPTiBwdWJsaWMucWh1Yl92ZXJpZnlfY29tbWVyY2lhbF9zY2hlbWEoKSBGUk9NIFBVQkxJQywgYW5vbiwgYXV0aGVudGljYXRlZA==', 'base64'), 'UTF8'),
    pg_catalog.convert_from(pg_catalog.decode('R1JBTlQgRVhFQ1VURSBPTiBGVU5DVElPTiBwdWJsaWMucWh1Yl92ZXJpZnlfY29tbWVyY2lhbF9zY2hlbWEoKSBUTyBzZXJ2aWNlX3JvbGU=', 'base64'), 'UTF8'),
    pg_catalog.convert_from(pg_catalog.decode('Q09NTUlU', 'base64'), 'UTF8')
  ];

  SELECT pg_catalog.md5(pg_catalog.string_agg(pg_catalog.octet_length(s)::text || ':' || s, '' ORDER BY ord)),
         pg_catalog.sum(pg_catalog.octet_length(s))
    INTO v_digest, v_bytes
    FROM pg_catalog.unnest(v_statements) WITH ORDINALITY t(s, ord);

  IF (pg_catalog.cardinality(v_statements) = c_stmt_count
      AND v_digest = c_stmt_digest
      AND v_bytes = c_stmt_bytes) IS DISTINCT FROM TRUE THEN
    RAISE EXCEPTION 'migration_history_payload_integrity: embedded statements decoded to cardinality=% digest=% bytes=% (expected % / % / %) - the artifact was corrupted in transfer. Nothing was changed. Re-copy with: Get-Content -Raw -Encoding UTF8 <file> | Set-Clipboard',
      pg_catalog.cardinality(v_statements), v_digest, v_bytes, c_stmt_count, c_stmt_digest, c_stmt_bytes;
  END IF;

  -- ==========================================================================
  -- STEP 1 — resolve and LOCK the history table BEFORE trusting any state.
  -- SHARE ROW EXCLUSIVE conflicts with every INSERT/UPDATE/DELETE writer and
  -- with itself; held through COMMIT. All gates below run AFTER this point.
  -- ==========================================================================
  v_reloid := pg_catalog.to_regclass('supabase_migrations.schema_migrations');
  IF v_reloid IS NULL THEN
    RAISE EXCEPTION 'unexpected_migration_history_shape: supabase_migrations.schema_migrations does not exist. This package does not create it - STOP and escalate.';
  END IF;

  LOCK TABLE supabase_migrations.schema_migrations IN SHARE ROW EXCLUSIVE MODE;

  -- Re-resolve after the lock: the OID must be unchanged (a concurrent drop and
  -- recreate would have required ACCESS EXCLUSIVE and a different OID).
  IF pg_catalog.to_regclass('supabase_migrations.schema_migrations') IS DISTINCT FROM v_reloid THEN
    RAISE EXCEPTION 'unexpected_migration_history_shape: the history table changed identity while acquiring the lock - STOP and escalate.';
  END IF;

  -- ==========================================================================
  -- STEP 2 — POST-LOCK: complete pinned verifier-authority contract.
  -- Independent of PRE 25; nothing outside this transaction is trusted.
  -- ==========================================================================
  v_oid := pg_catalog.to_regprocedure('public.qhub_verify_commercial_schema()');
  IF v_oid IS NULL THEN
    RAISE EXCEPTION 'unexpected_runtime_verifier_state: public.qhub_verify_commercial_schema() is missing. Nothing was changed - STOP and escalate.';
  END IF;

  IF (SELECT pg_catalog.count(*) FROM pg_catalog.pg_proc p
        JOIN pg_catalog.pg_namespace n ON n.oid = p.pronamespace
       WHERE n.nspname = 'public' AND p.proname = 'qhub_verify_commercial_schema') IS DISTINCT FROM 1 THEN
    RAISE EXCEPTION 'unexpected_runtime_verifier_state: the verifier is overloaded. Nothing was changed - STOP and escalate.';
  END IF;

  SELECT c.relowner INTO v_owner_oid FROM pg_catalog.pg_class c
   WHERE c.oid = pg_catalog.to_regclass('public.qhub_manual_review_requests');
  IF v_owner_oid IS NULL THEN
    RAISE EXCEPTION 'unexpected_runtime_verifier_authority: cannot resolve the contract owner from public.qhub_manual_review_requests. Nothing was changed.';
  END IF;

  SELECT r.oid INTO v_sr_oid FROM pg_catalog.pg_roles r WHERE r.rolname = 'service_role';
  IF v_sr_oid IS NULL THEN
    RAISE EXCEPTION 'unexpected_runtime_verifier_authority: role service_role does not exist. Nothing was changed.';
  END IF;

  SELECT pg_catalog.string_agg(fail, ', ') INTO v_detail FROM (
    SELECT 'body digest not approved' AS fail FROM pg_catalog.pg_proc p
      WHERE p.oid = v_oid AND (pg_catalog.md5(p.prosrc) IN (c_lf_digest, c_crlf_digest)) IS DISTINCT FROM TRUE
    UNION ALL
    SELECT 'signature/return/language/kind/volatility drift' FROM pg_catalog.pg_proc p
      JOIN pg_catalog.pg_language l ON l.oid = p.prolang
      WHERE p.oid = v_oid AND (
        pg_catalog.pg_get_function_identity_arguments(p.oid) = ''
        AND p.prorettype = 'pg_catalog.jsonb'::pg_catalog.regtype
        AND NOT p.proretset AND p.prokind = 'f' AND l.lanname = 'plpgsql'
        AND p.provolatile = 's'
      ) IS DISTINCT FROM TRUE
    UNION ALL
    SELECT 'not SECURITY DEFINER' FROM pg_catalog.pg_proc p
      WHERE p.oid = v_oid AND p.prosecdef IS DISTINCT FROM TRUE
    UNION ALL
    SELECT 'search_path drift' FROM pg_catalog.pg_proc p
      WHERE p.oid = v_oid AND (p.proconfig = c_search_path) IS DISTINCT FROM TRUE
    UNION ALL
    SELECT 'owner drift' FROM pg_catalog.pg_proc p
      WHERE p.oid = v_oid AND (p.proowner = v_owner_oid) IS DISTINCT FROM TRUE
    UNION ALL
    SELECT 'direct ACL cardinality <> 2' FROM pg_catalog.pg_proc p
      WHERE p.oid = v_oid
        AND ((SELECT pg_catalog.count(*) FROM pg_catalog.aclexplode(p.proacl)) = 2) IS DISTINCT FROM TRUE
    UNION ALL
    SELECT 'owner EXECUTE row missing or wrong' FROM pg_catalog.pg_proc p
      WHERE p.oid = v_oid AND NOT EXISTS (
        SELECT 1 FROM pg_catalog.aclexplode(p.proacl) ae
         WHERE ae.grantee = v_owner_oid AND ae.privilege_type = 'EXECUTE'
           AND ae.grantor = v_owner_oid AND NOT ae.is_grantable)
    UNION ALL
    SELECT 'service_role EXECUTE row missing or wrong' FROM pg_catalog.pg_proc p
      WHERE p.oid = v_oid AND NOT EXISTS (
        SELECT 1 FROM pg_catalog.aclexplode(p.proacl) ae
         WHERE ae.grantee = v_sr_oid AND ae.privilege_type = 'EXECUTE'
           AND ae.grantor = v_owner_oid AND NOT ae.is_grantable)
    UNION ALL
    SELECT 'unexpected direct grantee' FROM pg_catalog.pg_proc p
      WHERE p.oid = v_oid AND EXISTS (
        SELECT 1 FROM pg_catalog.aclexplode(p.proacl) ae
         WHERE ae.grantee <> v_owner_oid AND ae.grantee <> v_sr_oid)
    UNION ALL
    SELECT 'grant option present' FROM pg_catalog.pg_proc p
      WHERE p.oid = v_oid AND EXISTS (
        SELECT 1 FROM pg_catalog.aclexplode(p.proacl) ae WHERE ae.is_grantable)
    UNION ALL
    SELECT 'unexpected effective executor: ' || r.rolname
      FROM pg_catalog.pg_roles r
     WHERE pg_catalog.has_function_privilege(r.oid, v_oid, 'EXECUTE')
       AND NOT r.rolsuper AND r.oid <> v_owner_oid AND r.oid <> v_sr_oid
  ) s;
  IF v_detail IS NOT NULL THEN
    RAISE EXCEPTION 'unexpected_runtime_verifier_authority: % - the verifier authority contract is not met. Nothing was changed - STOP and escalate.', v_detail;
  END IF;

  -- ==========================================================================
  -- STEP 3 — POST-LOCK: the PRODUCT must verify READY. The authority gates
  -- above proved this is exactly the reviewed verifier, so this static,
  -- schema-qualified call executes only reviewed code. NULL-safe throughout: a
  -- NULL or malformed field can never satisfy a gate.
  -- ==========================================================================
  SELECT public.qhub_verify_commercial_schema() INTO v_json;

  IF (pg_catalog.jsonb_typeof(v_json) = 'object'
      AND (v_json ->> 'ready') = 'true'
      AND (v_json ->> 'expected_version') = c_product_ver
      AND pg_catalog.jsonb_typeof(v_json -> 'failed') = 'array'
      AND pg_catalog.jsonb_array_length(v_json -> 'failed') = 0) IS DISTINCT FROM TRUE THEN
    RAISE EXCEPTION 'migration_history_product_not_ready: verifier returned % - the database is not in the verified state; history must not be recorded. Nothing was changed.', coalesce(v_json::text, '(null)');
  END IF;

  -- ==========================================================================
  -- STEP 4 — POST-LOCK: the complete pinned CLI table contract. Any deviation
  -- that could broaden, redirect, or ambiguate the INSERT is a STOP.
  -- ==========================================================================
  SELECT pg_catalog.string_agg(fail, ', ') INTO v_detail FROM (
    SELECT 'not an ordinary permanent table' AS fail FROM pg_catalog.pg_class c
      WHERE c.oid = v_reloid
        AND (c.relkind = 'r' AND c.relpersistence = 'p' AND NOT c.relispartition) IS DISTINCT FROM TRUE
    UNION ALL
    SELECT 'table owner drift' FROM pg_catalog.pg_class c
      WHERE c.oid = v_reloid AND (c.relowner = v_owner_oid) IS DISTINCT FROM TRUE
    UNION ALL
    SELECT 'row-level security enabled' FROM pg_catalog.pg_class c
      WHERE c.oid = v_reloid AND (c.relrowsecurity OR c.relforcerowsecurity)
    UNION ALL
    SELECT 'column inventory drift'
      WHERE (SELECT pg_catalog.string_agg(a.attname || ':' || a.attnum::text || ':'
                      || pg_catalog.format_type(a.atttypid, a.atttypmod)
                      || ':' || a.attnotnull::text || ':' || a.atthasdef::text
                      || ':' || a.attidentity::text || ':' || a.attgenerated::text, '|' ORDER BY a.attnum)
               FROM pg_catalog.pg_attribute a
              WHERE a.attrelid = v_reloid AND a.attnum > 0 AND NOT a.attisdropped)
            IS DISTINCT FROM 'version:1:text:true:false::|statements:2:text[]:false:false::|name:3:text:false:false::'
    UNION ALL
    SELECT 'constraint inventory drift'
      WHERE (SELECT pg_catalog.string_agg(c.conname || ':' || c.contype::text, '|' ORDER BY c.conname)
               FROM pg_catalog.pg_constraint c WHERE c.conrelid = v_reloid)
            IS DISTINCT FROM 'schema_migrations_pkey:p'
    UNION ALL
    SELECT 'primary key is not exactly (version)'
      WHERE NOT EXISTS (SELECT 1 FROM pg_catalog.pg_constraint c
              WHERE c.conrelid = v_reloid AND c.contype = 'p'
                AND (SELECT pg_catalog.array_agg(att.attname::text ORDER BY k.ord)
                       FROM pg_catalog.unnest(c.conkey) WITH ORDINALITY k(attnum, ord)
                       JOIN pg_catalog.pg_attribute att
                         ON att.attrelid = c.conrelid AND att.attnum = k.attnum)
                    = ARRAY['version'])
    UNION ALL
    SELECT 'index inventory drift'
      WHERE (SELECT pg_catalog.string_agg(ic.relname || ':' || i.indisprimary::text, '|' ORDER BY ic.relname)
               FROM pg_catalog.pg_index i JOIN pg_catalog.pg_class ic ON ic.oid = i.indexrelid
              WHERE i.indrelid = v_reloid)
            IS DISTINCT FROM 'schema_migrations_pkey:true'
    UNION ALL
    SELECT 'trigger present'
      WHERE EXISTS (SELECT 1 FROM pg_catalog.pg_trigger t WHERE t.tgrelid = v_reloid)
    UNION ALL
    SELECT 'rewrite rule present'
      WHERE EXISTS (SELECT 1 FROM pg_catalog.pg_rewrite w WHERE w.ev_class = v_reloid)
    UNION ALL
    SELECT 'policy present'
      WHERE EXISTS (SELECT 1 FROM pg_catalog.pg_policy pol WHERE pol.polrelid = v_reloid)
    UNION ALL
    SELECT 'inheritance or partition linkage'
      WHERE EXISTS (SELECT 1 FROM pg_catalog.pg_inherits h
                     WHERE h.inhrelid = v_reloid OR h.inhparent = v_reloid)
  ) s;
  IF v_detail IS NOT NULL THEN
    RAISE EXCEPTION 'unexpected_migration_history_shape: % - the live history table does not match the pinned CLI contract. Nothing was changed - STOP and escalate.', v_detail;
  END IF;

  -- ==========================================================================
  -- STEP 5 — POST-LOCK: conflict refusal. Malformed versions are detected
  -- BEFORE any ordered comparison, so no value can evade the newer-version
  -- check. Ambiguity is a human decision, never a repair.
  -- ==========================================================================
  SELECT pg_catalog.count(*) INTO v_malformed
    FROM supabase_migrations.schema_migrations
   WHERE (version ~ '^[0-9]+$') IS DISTINCT FROM TRUE;
  IF v_malformed IS DISTINCT FROM 0 THEN
    RAISE EXCEPTION 'migration_history_conflict: % history row(s) carry a malformed (non-numeric) version - ordered comparison is unsafe. Nothing was changed - STOP and escalate.', v_malformed;
  END IF;

  SELECT pg_catalog.count(*) INTO v_newer
    FROM supabase_migrations.schema_migrations
   WHERE version::pg_catalog.numeric > c_version::pg_catalog.numeric;
  IF v_newer IS DISTINCT FROM 0 THEN
    RAISE EXCEPTION 'migration_history_conflict: % history row(s) carry a version newer than %, which no committed migration explains. Nothing was changed - STOP and escalate.', v_newer, c_version;
  END IF;

  SELECT pg_catalog.count(*) INTO v_name_conf
    FROM supabase_migrations.schema_migrations
   WHERE name IS NOT DISTINCT FROM c_name AND version IS DISTINCT FROM c_version;
  IF v_name_conf IS DISTINCT FROM 0 THEN
    RAISE EXCEPTION 'migration_history_conflict: name % is recorded under % other version(s). Nothing was changed - STOP and escalate.', c_name, v_name_conf;
  END IF;

  SELECT pg_catalog.count(*) INTO v_target
    FROM supabase_migrations.schema_migrations
   WHERE version = c_version;

  SELECT pg_catalog.count(*) INTO v_exact
    FROM supabase_migrations.schema_migrations m
   WHERE m.version = c_version
     AND m.name IS NOT DISTINCT FROM c_name
     AND m.statements IS NOT NULL
     AND pg_catalog.cardinality(m.statements) = c_stmt_count
     AND (SELECT pg_catalog.md5(pg_catalog.string_agg(pg_catalog.octet_length(s)::text || ':' || s, '' ORDER BY ord))
            FROM pg_catalog.unnest(m.statements) WITH ORDINALITY t(s, ord)) = c_stmt_digest;

  IF v_target IS DISTINCT FROM 0 AND v_exact IS DISTINCT FROM v_target THEN
    RAISE EXCEPTION 'migration_history_conflict: version % is recorded with an unexpected name or NULL/incomplete/different statements. This artifact never updates or overwrites - STOP and escalate.', c_version;
  END IF;

  -- ==========================================================================
  -- STEP 6 — RECORD (or true no-op), then capture the audit evidence from this
  -- same transaction. The lock is held until COMMIT.
  -- ==========================================================================
  IF v_target = 0 THEN
    INSERT INTO supabase_migrations.schema_migrations (version, name, statements)
    VALUES (c_version, c_name, v_statements);
    v_action := 'RECORDED_NOW';
  ELSE
    v_action := 'ALREADY_RECORDED_EXACTLY';
  END IF;

  SELECT pg_catalog.count(*) INTO v_target
    FROM supabase_migrations.schema_migrations WHERE version = c_version;
  SELECT pg_catalog.count(*) INTO v_total
    FROM supabase_migrations.schema_migrations;

  INSERT INTO pg_temp.r15_6_migration_history_audit
    (recorded_at, action, history_version, history_name,
     statements_cardinality, statements_digest, statements_total_bytes,
     rows_for_version, total_history_rows)
  SELECT pg_catalog.now(), v_action, m.version, m.name,
         pg_catalog.cardinality(m.statements),
         (SELECT pg_catalog.md5(pg_catalog.string_agg(pg_catalog.octet_length(s)::text || ':' || s, '' ORDER BY ord))
            FROM pg_catalog.unnest(m.statements) WITH ORDINALITY t(s, ord)),
         (SELECT pg_catalog.sum(pg_catalog.octet_length(s))
            FROM pg_catalog.unnest(m.statements) t(s)),
         v_target, v_total
    FROM supabase_migrations.schema_migrations m
   WHERE m.version = c_version;

  IF (SELECT pg_catalog.count(*) FROM pg_temp.r15_6_migration_history_audit) IS DISTINCT FROM 1 THEN
    RAISE EXCEPTION 'migration_history_conflict: audit capture did not produce exactly one row - rolling back.';
  END IF;
END;
$r15_6_record$;

COMMIT;

-- ---------------------------------------------------------------------------
-- AUDIT RECORD — reads ONLY the evidence captured inside the committed
-- transaction (the pg_temp table); it does not re-query durable state. POST 27
-- is the certification of durable state. Capture this output verbatim.
-- ---------------------------------------------------------------------------
SELECT recorded_at, action, history_version, history_name,
       statements_cardinality, statements_digest, statements_total_bytes,
       rows_for_version, total_history_rows
  FROM pg_temp.r15_6_migration_history_audit;
